def _terminate_process_group(process, grace_seconds, *, killpg=os.killpg,
                             clock=time.monotonic, sleep=time.sleep):
    """Stop the evaluator session; systemd remains the cgroup-level backstop."""
    process_group = process.pid

    def exists():
        try:
            killpg(process_group, 0)
        except ProcessLookupError:
            return False
        return True

    try:
        killpg(process_group, signal.SIGTERM)
    except ProcessLookupError:
        return process.wait()
    deadline = clock() + grace_seconds
    exit_code = None
    while exists() and clock() < deadline:
        try:
            exit_code = process.wait(timeout=min(0.2, max(0.0, deadline - clock())))
        except subprocess.TimeoutExpired:
            pass
        if exists():
            sleep(min(0.1, max(0.0, deadline - clock())))
    if exists():
        try:
            killpg(process_group, signal.SIGKILL)
        except ProcessLookupError:
            pass
    kill_deadline = clock() + 5
    while exists() and clock() < kill_deadline:
        sleep(min(0.1, max(0.0, kill_deadline - clock())))
    if exists():
        raise RuntimeError("evaluator process group survived SIGKILL")
    if exit_code is None:
        exit_code = process.wait()
    return exit_code


