               "-test.timeout=0"]
    with process_log.open("wb") as log:
        process = process_factory(command, env=environment, cwd=root, stdout=log,
                                  stderr=subprocess.STDOUT, start_new_session=True)
        supervision_failure = None
        if supervision_check is None:
            exit_code = process.wait()
        else:
            while True:
                try:
                    supervision_check()
                    if watchdog_heartbeat is not None:
                        watchdog_heartbeat()
                except Exception as error:
                    supervision_failure = str(error)
                    exit_code = terminate_fn(process, stop_grace_seconds)
                    break
                try:
                    exit_code = process.wait(timeout=poll_seconds)
                    break
                except subprocess.TimeoutExpired:
                    continue
    raw_time = time_path.read_text() if time_path.is_file() else ""
    try:
        peak_rss_bytes = parse_peak_rss_bytes(raw_time)
