// (`func (a *T) M(...)` -> "a"), so a.field accesses resolve to the enclosing
// type. Empty for non-Go or non-method signatures.
func goReceiverVar(signature string) string {
	if m := goReceiverRe.FindStringSubmatch(signature); m != nil {
		return m[1]
	}
	return ""
