  channel_id?: string;
  // File ID returned by slack_get_file_upload_url (e.g., 'F0ABC12345')
  file_id: string;
  // Message text to accompany the file when shared
  initial_comment?: string;
  // Message timestamp to upload as a thread reply
  thread_ts?: string;
  // Display title for the file
  title?: string;
