		if index < 20 {
			body = fmt.Sprintf("package p\nfunc F%05d( { /* needle */\n", index)
		}
		write(t, repo, path, body)
	}
	git(t, repo, "add", ".")
	git(t, repo, "commit", "-m", "large captured preselection fixture")

