// capturedPreselectionMatches samples fixed-string matches from the operation's
// reader. It never asks Git to reopen source content. Like Git's -m option, the
// budget counts matching lines, not substrings; -o selects nonoverlapping,
// leftmost-longest matches. Only distinct matched strings need be retained for
// the downstream term-presence reduction.
func capturedPreselectionMatches(ctx context.Context, source sourceContext, tracked, patterns []string, maxLines int, observers ...*capturePreselectionObserver) ([]gitutil.GrepMatch, int, error) {
	if len(observers) > 0 && observers[0] != nil {
		observers[0].activate()
	}
	prototype, err := newCaptureMatchStream(ctx, patterns, maxLines, nil)
	if err != nil {
		return nil, 0, err
	}
	terms := make([]string, len(patterns))
	for index, pattern := range patterns {
		terms[index] = strings.ToLower(pattern)
	}
	if len(observers) > 0 && observers[0] != nil {
		terms = observers[0].terms
	}
	termMatcher := newSearchTermMatcher(terms)
	allowed := make(map[string]bool, len(source.paths))
	for _, path := range source.paths {
		allowed[path] = true
	}
	eligible := make([]string, 0, len(tracked))
	for _, path := range tracked {
		if allowed[path] {
			eligible = append(eligible, path)
		}
	}
	attributes, err := source.capturedDiffAttributes(ctx, eligible)
	if err != nil {
		return nil, 0, err
	}
	matches := make([]gitutil.GrepMatch, 0)
	reads := 0
	for _, path := range tracked {
		if err := ctx.Err(); err != nil {
			return nil, reads, err
		}
		if !allowed[path] {
			continue
		}
		content, ok := source.read(path)
		if len(observers) > 0 && observers[0] != nil {
			if evidence, observed := observers[0].evidence(path); observed {
				if evidence.err != nil {
					return nil, reads, evidence.err
				}
				reads++
				attribute := attributes[path]
				if !attribute.Binary && (attribute.Text || !evidence.binary) {
					if evidence.matched && len(evidence.terms) == 0 {
						matches = append(matches, gitutil.GrepMatch{Path: path})
					}
					for _, term := range evidence.terms {
						matches = append(matches, gitutil.GrepMatch{Path: path, Text: term})
					}
				}
				continue
			}
		}
		if !ok {
			continue
		}
		reads++
		stream := *prototype
		seen := make([]bool, len(terms))
		stream.emit = func(text string) {
			for index, matched := range termMatcher.match(text) {
				seen[index] = seen[index] || matched
			}
		}
		if _, err := stream.Write([]byte(content)); err != nil {
			return nil, reads, err
		}
		if err := stream.finish(); err != nil {
			return nil, reads, err
		}
		attribute := attributes[path]
		if !attribute.Binary && (attribute.Text || !stream.binary) {
			if stream.matched {
				matches = append(matches, gitutil.GrepMatch{Path: path})
			}
			for index, matched := range seen {
				if matched {
					matches = append(matches, gitutil.GrepMatch{Path: path, Text: terms[index]})
				}
			}
		}

	}
	return matches, reads, nil
}
// least two letter-bearing words and not one lowercase letter among them. One all-caps word
// is an identifier a caller typed; a whole all-caps sentence is emphasis.
func searchQueryIsShouted(tokens []string) bool {
	lettered := 0
	for _, token := range tokens {
		hasLetter := false
		for _, character := range token {
			if !unicode.IsLetter(character) {
				continue
			}
			hasLetter = true
			if unicode.IsLower(character) {
				return false
			}
		}
		if hasLetter {
			lettered++
		}
	}
	return lettered >= 2
}

// searchQueryUnmatchableWord returns the predicate "this query word cannot contribute a
// match to ANY document in the corpus": either it never became a search term (a stop word,
// or too short to index), or it is a term no indexed file contains. Such a word is inert
// evidence, and inert evidence may not cost a document points it already earned.
// documentFrequency may be nil before corpus statistics exist, in which case only the
// never-became-a-term half of the test applies.
func searchQueryUnmatchableWord(termSet map[string]bool, documentFrequency map[string]int) func(string) bool {
	return func(word string) bool {
		if !termSet[word] {
			return true
		}
		if documentFrequency == nil {
			return false
		}
		return documentFrequency[word] == 0
	}
}

// matchableQueryWords drops from the written word order every word that cannot contribute a
// match to any document, so the phrase the caller meant survives the noise words around it.
func matchableQueryWords(wordSequence []string, termSet map[string]bool, documentFrequency map[string]int) []string {
	unmatchable := searchQueryUnmatchableWord(termSet, documentFrequency)
	matchable := make([]string, 0, len(wordSequence))
	for _, word := range wordSequence {
		if unmatchable(word) {
			continue
		}
		matchable = append(matchable, word)
	}
	return matchable
}

// withCorpusPresence returns a copy of q that knows which of its words the corpus can
// actually match, so scoring stops charging documents for words nothing contains.
// documentFrequency is keyed by term over the indexed file set.
func (q searchQuery) withCorpusPresence(documentFrequency map[string]int) searchQuery {
	q.matchableWords = matchableQueryWords(q.wordSequence, q.termSet, documentFrequency)
	return q
}

func buildSparseSearchQuery(query string) searchQuery {
	return buildSparseSearchQueryExpanded(query, buildSearchQuery(query))
}

func buildSparseSearchQueryExpanded(query string, expanded searchQuery) searchQuery {
	// Same strip as buildSearchQuery: the sparse half of hybrid search must not be scored
	// against a term set the dense half never sees, and its own cap
	// (maxSparseSearchQueryTerms) is filled first-come, so URL debris starves it too.
	query = stripSearchQueryURLState(query)
	terms := make([]string, 0, maxSparseSearchQueryTerms)
	termSet := make(map[string]bool, maxSparseSearchQueryTerms)
	weights := make(map[string]float64, maxSparseSearchQueryTerms)
	for _, term := range sparseSearchTokens(query) {
		if len(term) < 2 || sparseSearchStopWords[term] || termSet[term] {
			continue
		}
		termSet[term] = true
		weights[term] = 1
		terms = append(terms, term)
		if len(terms) == maxSparseSearchQueryTerms {
			break
		}
	}
	compounds := map[string]bool{}
	compoundTokens := searchCompoundWordPattern.FindAllString(query, -1)
	for index := range compoundTokens {
		for _, joined := range searchCompoundJoins(compoundTokens, index) {
			compounds[joined] = true
		}
	}
	aliases := map[string]bool{}
	for _, term := range expanded.terms {
		if !expanded.inferredAbbreviations[term] && !compounds[term] {
			continue
		}
		if termSet[term] || len(terms) >= maxSparseSearchQueryTerms {
			continue
		}
		terms = append(terms, term)
		termSet[term] = true
		weights[term] = expanded.weights[term]
		if expanded.inferredAbbreviations[term] {
			aliases[term] = true
		}
	}
	rawLower := strings.ToLower(strings.TrimSpace(query))
	wordSequence := searchQueryWordSequence(rawLower)
	return searchQuery{
		rawLower:              rawLower,
		terms:                 terms,
		termSet:               termSet,
		weights:               weights,
		inferredAbbreviations: aliases,
		aliasTokens:           searchAliasTokenIndex(terms, aliases),
		words:                 searchQueryWords(rawLower),
		wordSequence:          wordSequence,
		matchableWords:        matchableQueryWords(wordSequence, termSet, nil),
	}
}

