package sem

import (
	"context"
	"strings"

	"github.com/entireio/entire-graph/internal/gitutil"
)

// capturedPreselectionMatches samples fixed-string matches from the operation's
// reader. It never asks Git to reopen source content. Like Git's -m option, the
// budget counts matching lines, not substrings; -o selects nonoverlapping,
// leftmost-longest matches. Only distinct matched strings need be retained for
// the downstream term-presence reduction.
func capturedPreselectionMatches(ctx context.Context, source sourceContext, tracked, patterns []string, maxLines int, observers ...*capturePreselectionObserver) ([]gitutil.GrepMatch, int, error) {
	if len(observers) > 0 && observers[0] != nil {
		observers[0].activate()
	}
	prototype, err := newCaptureMatchStream(ctx, patterns, maxLines, nil)
	if err != nil {
		return nil, 0, err
	}
	terms := make([]string, len(patterns))
	for index, pattern := range patterns {
		terms[index] = strings.ToLower(pattern)
	}
	if len(observers) > 0 && observers[0] != nil {
		terms = observers[0].terms
	}
	termMatcher := newSearchTermMatcher(terms)
	allowed := make(map[string]bool, len(source.paths))
	for _, path := range source.paths {
		allowed[path] = true
	}
	eligible := make([]string, 0, len(tracked))
	for _, path := range tracked {
		if allowed[path] {
			eligible = append(eligible, path)
		}
	}
	attributes, err := source.capturedDiffAttributes(ctx, eligible)
	if err != nil {
		return nil, 0, err
	}
	matches := make([]gitutil.GrepMatch, 0)
	reads := 0
	for _, path := range tracked {
		if err := ctx.Err(); err != nil {
			return nil, reads, err
		}
		if !allowed[path] {
			continue
		}
		content, ok := source.read(path)
		if len(observers) > 0 && observers[0] != nil {
			if evidence, observed := observers[0].evidence(path); observed {
				if evidence.err != nil {
					return nil, reads, evidence.err
				}
				reads++
				attribute := attributes[path]
				if !attribute.Binary && (attribute.Text || !evidence.binary) {
					if evidence.matched && len(evidence.terms) == 0 {
						matches = append(matches, gitutil.GrepMatch{Path: path})
					}
					for _, term := range evidence.terms {
						matches = append(matches, gitutil.GrepMatch{Path: path, Text: term})
					}
				}
				continue
			}
		}
		if !ok {
			continue
		}
		reads++
		stream := *prototype
		seen := make([]bool, len(terms))
		stream.emit = func(text string) {
			for index, matched := range termMatcher.match(text) {
				seen[index] = seen[index] || matched
			}
		}
		if _, err := stream.Write([]byte(content)); err != nil {
			return nil, reads, err
		}
		if err := stream.finish(); err != nil {
			return nil, reads, err
		}
		attribute := attributes[path]
		if !attribute.Binary && (attribute.Text || !stream.binary) {
			if stream.matched {
				matches = append(matches, gitutil.GrepMatch{Path: path})
			}
			for index, matched := range seen {
				if matched {
					matches = append(matches, gitutil.GrepMatch{Path: path, Text: terms[index]})
				}
			}
		}

	}
	return matches, reads, nil
}
}

func committedSearchFiles(paths, matches []string, q searchQuery) []string {
	allowed := make(map[string]bool, len(paths))
	for _, filePath := range paths {
		allowed[filePath] = true
	}
	matched := make(map[string]bool, len(matches))
	for _, match := range matches {
		if allowed[match] {
			matched[match] = true
		}
	}
	files := make([]searchFileCandidate, 0, len(matched)+16)
	for _, filePath := range paths {
		pathScore := pathSearchScore(q, filePath)
		if !matched[filePath] && pathScore == 0 {
			continue
		}
		files = append(files, searchFileCandidate{
			path:  filePath,
			score: 2*pathScore + searchPathPrior(q, filePath),
		})
	}
	sort.Slice(files, func(i, j int) bool {
		if files[i].score != files[j].score {
			return files[i].score > files[j].score
		}
		return canonicalSearchPathLess(files[i].path, files[j].path)
	})
	selected := make([]string, len(files))
	for index, file := range files {
		selected[index] = file.path
	}
	return selected
}

func scoreSearchPaths(
	ctx context.Context,
	paths []string,
	workers int,
	score func(string) (searchFileCandidate, bool),
) []searchFileCandidate {
	initialCapacity := minInt(len(paths), 1024)
	if workers <= 1 {
		files := make([]searchFileCandidate, 0, initialCapacity)
		for _, filePath := range paths {
			if ctx.Err() != nil {
				break
			}
			if candidate, ok := score(filePath); ok {
				files = append(files, candidate)
			}
		}
		return files
	}

	jobs := make(chan string)
	results := make(chan searchFileCandidate)
	var wait sync.WaitGroup
	for worker := 0; worker < workers; worker++ {
		wait.Add(1)
		go func() {
			defer wait.Done()
			for filePath := range jobs {
				if ctx.Err() != nil {
					return
				}
				if candidate, ok := score(filePath); ok {
					select {
					case results <- candidate:
					case <-ctx.Done():
						return
					}
				}
			}
		}()
	}
	go func() {
		defer close(jobs)
		for _, filePath := range paths {
			select {
			case jobs <- filePath:
			case <-ctx.Done():
				return
			}
		}
	}()
	go func() {
		wait.Wait()
		close(results)
	}()
	files := make([]searchFileCandidate, 0, initialCapacity)
	for candidate := range results {
		files = append(files, candidate)
	}
	return files
}

func shouldUseGitGrepPreselection(worktree bool, fileCount int) bool {
	return worktree && fileCount >= minGitGrepPreselectionFiles
}

func searchPreselectionPatterns(q searchQuery) []string {
	const (
		maxPatterns            = 12
		maxPrimaryPatterns     = 8
		maxInitialCodePatterns = 4
		maxOriginalPatterns    = 4
		maxMorphPatterns       = 2
		maxFragmentTerms       = 2
	)
	patterns := make([]string, 0, maxPatterns)
	seen := make(map[string]bool, maxPatterns)
	appendTier := func(limit int, include func(float64) bool) {
		if limit <= 0 {
			return
		}
		added := 0
		for _, term := range q.terms {
			if seen[term] || !include(q.weights[term]) {
				continue
			}
			patterns = append(patterns, term)
			seen[term] = true
			added++
			if added == limit || len(patterns) == maxPatterns {
				return
			}
		}
	}
	appendTier(maxInitialCodePatterns, func(weight float64) bool {
		return weight >= 1.25
	})
	appendTier(maxOriginalPatterns, func(weight float64) bool {
		return weight == 1
	})
	appendTier(maxPrimaryPatterns-len(patterns), func(weight float64) bool {
		return weight >= 1.25 || weight == 1
	})
	appendTier(maxMorphPatterns, func(weight float64) bool {
		return weight < 1
	})
	appendTier(maxFragmentTerms, func(weight float64) bool {
		return weight > 1 && weight < 1.25
	})
	appendTier(maxPatterns-len(patterns), func(weight float64) bool {
		return weight >= 1.25 || weight == 1
	})
	return patterns
}

func searchGitGrepPreselectionPatterns(q searchQuery) []string {
	patterns := searchPreselectionPatterns(q)
	// Each additional fixed-string pattern makes Git scan and emit more of a
	// large index. Preserve one derived morphological/fragment fallback rather
	// than letting direct terms consume the entire bounded pattern budget.
	if len(patterns) <= 6 {
		return patterns
	}
	direct := make([]string, 0, 6)
	derived := make([]string, 0, 1)
	for _, pattern := range patterns {
		if q.weights[pattern] >= 1 {
			direct = append(direct, pattern)
		} else {
			derived = append(derived, pattern)
		}
	}
	limit := 6
	if len(derived) > 0 {
		limit--
	}
	if len(direct) > limit {
		direct = direct[:limit]
	}
	if len(derived) > 0 {
		direct = append(direct, derived[0])
	}
	return direct
}

