			strings.Contains(r.ToID, "method:Conn.WriteMessage") {
			found = true
		}
	}
	if !found {
		t.Fatalf("in-module qualified receiver ws *app.Conn: expected ws.WriteMessage() -> Conn.WriteMessage edge, got none")
	}
}

