	}
	components, ok := r.anchor.components(path)
	if !ok {
		return errSymlinkChainOffVolume
	}
	rel := "."
	if len(components) > 0 {
		rel = filepath.Join(components...)
	}
	return r.mounts.beforeLookup(rel)
}

